CREATE TABLE IF NOT EXISTS profiles (user_id TEXT PRIMARY KEY, language TEXT NOT NULL DEFAULT 'it', theme TEXT NOT NULL DEFAULT 'dark', avatar_url TEXT NOT NULL DEFAULT '', interests JSONB NOT NULL DEFAULT '[]'::jsonb, first_name TEXT NOT NULL DEFAULT '', last_name TEXT NOT NULL DEFAULT '', display_name TEXT NOT NULL DEFAULT '', memory_enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now())